const inp = $input.first().json;
const path = String(inp.path || '').trim();
const query = inp.query && typeof inp.query === 'object' ? inp.query : {};
if (path === '') {
  return [{ json: { ok: false, reason: 'no_path', path: '', data: null } }];
}
const ALLOWED = [
  /^\/v1\/events$/,
  /^\/v1\/events\/to-plan$/,
  /^\/v1\/intervention\/\d+$/,
  /^\/v1\/client\/\d+$/,
  /^\/v1\/client\/\d+\/events$/,
  /^\/v1\/billing\/quotations$/,
  /^\/v1\/billing\/quotations\/[0-9a-fA-F-]{36}$/
];
if (!ALLOWED.some(r => r.test(path))) {
  throw new Error('Interfast - Lecture : chemin refuse par la liste blanche : ' + path);
}
const parts = [];
for (const [k, v] of Object.entries(query)) {
  if (v === undefined || v === null || v === '') continue;
  if (Array.isArray(v)) {
    for (const x of v) parts.push(encodeURIComponent(k) + '=' + encodeURIComponent(String(x)));
  } else {
    parts.push(encodeURIComponent(k) + '=' + encodeURIComponent(String(v)));
  }
}
const url = 'https://app.inter-fast.fr' + path + (parts.length ? '?' + parts.join('&') : '');
return [{ json: { ok: true, path: path, url: url } }];

const BLOCK = new Set([
  'purchasePrice', 'purchaseAmount', 'hourlyCost', 'hiddenFeesPercentage',
  'firebaseNotificationTokens', 'password', 'salt', 'confirmationCode',
  'emailSignature', 'accountingNumber'
]);
function clean(v) {
  if (Array.isArray(v)) return v.map(clean);
  if (v && typeof v === 'object') {
    const o = {};
    for (const [k, x] of Object.entries(v)) {
      if (!BLOCK.has(k)) o[k] = clean(x);
    }
    return o;
  }
  return v;
}
const items = $input.all().map(i => i.json);
const body = items.length === 1 ? items[0] : items;
const path = $('Liste blanche GET').first().json.path;
return [{ json: { ok: true, path: path, data: clean(body) } }];
